class Solution {
public:
    string largestMultipleOfThree(vector<int>& digits) {
        int count[10] = {0};
        int sum = 0;
        for (int d : digits) {
            count[d]++;
            sum += d;
        }

        int r = sum % 3;
        if (r == 1) {
            if (count[1] > 0) count[1]--;
            else if (count[4] > 0) count[4]--;
            else if (count[7] > 0) count[7]--;
            else {
                int removed = 0;
                for (int d : {2, 5, 8}) {
                    while (count[d] > 0 && removed < 2) {
                        count[d]--;
                        removed++;
                    }
                }
            }
        } else if (r == 2) {
            if (count[2] > 0) count[2]--;
            else if (count[5] > 0) count[5]--;
            else if (count[8] > 0) count[8]--;
            else {
                int removed = 0;
                for (int d : {1, 4, 7}) {
                    while (count[d] > 0 && removed < 2) {
                        count[d]--;
                        removed++;
                    }
                }
            }
        }

        string result;
        for (int d = 9; d >= 0; d--) {
            if (count[d] > 0) {
                result.append(count[d], static_cast<char>('0' + d));
            }
        }

        if (result.empty()) return "";
        if (result[0] == '0') return "0";
        return result;
    }
};
